<script setup lang="ts">
import { computed, ref, nextTick } from 'vue'
import { lessons, type Question } from '../data/content'
import { useLearning } from '../stores/learning'
import { useNavigation } from '../stores/navigation'
import AppIcon from '../components/AppIcon.vue'
const store=useLearning(),nav=useNavigation()
const selected=ref(lessons.some(l=>l.id===store.state.lastLesson)?store.state.lastLesson!:store.nextLesson.id)
const lesson=computed(()=>lessons.find(l=>l.id===selected.value)!)
const questions=ref<Question[]>([]),index=ref(0),answer=ref<number|null>(null),correct=ref(0),active=ref(false),finished=ref(false)
const current=computed(()=>questions.value[index.value])
const queuedCount=computed(()=>lesson.value.quiz.filter(q=>store.state.wrongQuestions.includes(q.id)).length)
function start(){questions.value=[...lesson.value.quiz].sort((a,b)=>Number(store.state.wrongQuestions.includes(b.id))-Number(store.state.wrongQuestions.includes(a.id)));index.value=0;answer.value=null;correct.value=0;finished.value=false;active.value=true;focusQuestion()}
async function focusQuestion(){await nextTick();document.getElementById('quiz-heading')?.focus()}
function choose(value:number){if(answer.value!==null || !current.value)return;answer.value=value;const isCorrect=value===current.value.answer;if(isCorrect)correct.value++;store.recordAnswer(current.value.id,isCorrect)}
function next(){if(answer.value===null)return;if(index.value===questions.value.length-1){store.finishQuiz(lesson.value.id,Math.round(correct.value/questions.value.length*100));finished.value=true;active.value=false}else{index.value++;answer.value=null}focusQuestion()}
</script>
<template><div class="page-heading"><div><p class="eyebrow">PAHAMI, BUKAN SEKADAR HAFAL</p><h1>Latihan dan kuis</h1><p>Jawaban yang belum tepat adalah kesempatan untuk belajar lagi.</p></div></div><section v-if="!active && !finished" class="card quiz-intro"><span class="badge neutral">{{lesson.quiz.length}} soal · Tanpa batas waktu</span><h2>Luangkan waktu untuk memahami</h2><p class="muted">Pilih pelajaran yang ingin kamu latih. Penjelasan akan muncul setelah setiap jawaban.</p><label for="quiz-lesson" class="field-label">Pelajaran</label><select id="quiz-lesson" v-model="selected" class="form-input"><option v-for="l in lessons" :key="l.id" :value="l.id">{{l.title}}</option></select><p v-if="queuedCount" class="callout">{{queuedCount}} soal dari sesi sebelumnya akan muncul lebih dahulu. Mari coba pelan-pelan.</p><div class="button-row"><button class="button primary" @click="start">Mulai latihan<AppIcon name="arrow" :size="16"/></button><button class="button secondary" @click="nav.go('lesson',lesson.id)">Baca pelajaran dahulu</button></div></section><section v-else-if="active && current" class="card quiz-session"><div class="section-header"><span class="badge neutral">{{lesson.title}}</span><span class="muted text-sm">Soal {{index+1}} dari {{questions.length}}</span></div><div class="progress-track"><span :style="{width:index/questions.length*100+'%'}"></span></div><fieldset :key="current.id" class="quiz-fieldset"><legend id="quiz-heading" tabindex="-1">{{current.prompt}}</legend><button v-for="(option,i) in current.options" :key="i" :class="['quiz-option',{'chosen':answer===i,'correct-option':answer!==null && i===current.answer,'wrong-option':answer===i && i!==current.answer}]" :disabled="answer!==null" @click="choose(i)"><span class="option-letter">{{String.fromCharCode(65+i)}}</span><span>{{option}}</span><AppIcon v-if="answer!==null && i===current.answer" name="check" :size="18"/></button></fieldset><div v-if="answer!==null" class="answer-feedback" aria-live="polite"><h3>{{answer===current.answer?'Ya, tepat.':'Mari kita pahami bersama.'}}</h3><p>{{current.explanation}}</p><p class="small-note"><a v-for="source in lesson.sumber.filter(s=>current!.sourceIds.includes(s.id))" :key="source.id" :href="source.url" target="_blank" rel="noopener noreferrer">{{source.title}} ↗ </a></p><button class="button primary" @click="next">{{index===questions.length-1?'Selesaikan latihan':'Soal berikutnya'}}<AppIcon name="arrow" :size="16"/></button></div></section><section v-else class="card empty-state"><span class="success-symbol"><AppIcon name="check" :size="30"/></span><h2 id="quiz-heading" tabindex="-1">Satu langkah baru, sudah kamu tempuh.</h2><p>{{correct}} dari {{questions.length}} jawaban tepat.</p><p v-if="!store.state.progress[lesson.id]?.readAt" class="muted">Tandai pelajaran sudah dibaca agar progres pelajaran ini lengkap.</p><p v-else class="muted">Pelajaran ini sudah tercatat selesai. Kamu tetap bisa mengulangnya.</p><p v-if="queuedCount" class="text-sm muted">{{queuedCount}} soal akan diulang pada sesi berikutnya.</p><div class="button-row"><button class="button primary" @click="nav.go('lesson',lesson.id)">Kembali ke pelajaran</button><button class="button secondary" @click="start">Latihan lagi</button><button class="button ghost" @click="finished=false">Pilih pelajaran lain</button></div></section></template>
